(* [comment removed for export] *)
Ltac y4_log_in WINS W LIN :=
  lazymatch goal with
  | KXLF : log_flat ?E ?log, HK : know_ok ?segs ?E ?m0' ?kn |- _ =>
    let b := eval unfold E in E in
    lazymatch b with kx_env (map (Z_to_bv 64) ?zv) ?xs =>
      let wz0 := kx_wins_reify WINS zv in
      let wz := eval vm_compute in wz0 in
      let LI := fresh "LI" in
      assert (LI : log_inside E log (map (win_ivl E) wz))
        by exact (kx_log_in_ok segs E m0' kn wz log HK ltac:(vm_compute; reflexivity));
      assert (LIN : log_inside E log W);
      [ apply (log_inside_mono E log _ W LI); clear LI; intros ? ?; cbn [map inside win_ivl fst snd];
        let na := eval vm_compute in (length zv) in
        change E with (kE zv xs);
        repeat match goal with
        | |- context [estart (kE zv xs) ?a] =>
            rewrite (estart_ez_kE zv xs a);
            [ | cbv [ez a_base a_off]; change (length zv) with na; cbv [nth Nat.ltb Nat.leb]; lia ]
        end;
        rewrite ?elenZ_lit by lia;
        cbv [ez a_base a_off]; change (length zv) with na; cbv [nth Nat.ltb Nat.leb]; lia
      | clear LI ]
    end
  end.

Section CANSEC1. Context {rc : runConstT}.
Section Y4S1K.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m0 : fmem).
  Variables (DST dcap SS DT mtl tl lo : Z) (src : list Z) (cells : list deltX2) (cbs : list byte).
  Notation SP := (bv_unsigned sp).
  Notation n := (zlen src).
  Hypothesis TOK : x2_table_ok cells tl.
  Hypothesis ECB : cbs = firstn (Z.to_nat (4 * 2^tl)) (x2_bytes' cells).
  Hypothesis LCB : zlen cbs = 4 * 2^tl.
  Hypothesis MTL : 1 <= mtl <= 12.
  Hypothesis TLM : tl <= mtl.
  Hypothesis D0 : 0 <= DST.
  Hypothesis DP : 0 < dcap -> 8 <= DST.
  Hypothesis DC : 0 <= dcap < 2^32.
  Hypothesis DL : DST + dcap <= lo.
  Hypothesis S0 : 16 <= SS.
  Hypothesis SL : SS + n <= lo.
  Hypothesis NSM : n < 2^26.
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis DT0 : 0 < DT.
  Hypothesis CBL : DT + 4 + 4 * 2^tl <= lo.
  Hypothesis DJ1 : DT + 4 + 4 * 2^tl <= DST \/ DST + dcap <= DT.
  Hypothesis DJ3 : DST + dcap <= SS \/ SS + n <= DST.
  Hypothesis LOS : lo <= SP - 4096.
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis SP47 : SP <= 2^47.
  Hypothesis DT4 : DT mod 4 = 0.

  Notation POST := (huf_dec_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc DST dcap lo m0).
  Notation Y4F' mm spl b4 b3 b2 b1 :=
    (Y4F ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT lo src cbs mm spl b4 b3 b2 b1).

  Variables (L1 L2 L3 L4 SEG : Z).
  Notation O2 := (6 + L1). Notation O3 := (6 + L1 + L2). Notation O4 := (6 + L1 + L2 + L3).
  Hypothesis HL : 1 <= L1 /\ 1 <= L2 /\ 1 <= L3 /\ 1 <= L4 /\ 6 + L1 + L2 + L3 + L4 <= n.
  Hypothesis HQ : 0 < SEG /\ 3 * SEG <= dcap /\ dcap <= 4 * SEG.
  Hypothesis HQ2 : 2 <= SEG.
  Notation desc := (tl + 256 * mtl).

  Notation SPLL w64 k4 k2 p2 k1 j0 :=
    (SPLB desc (DST + 3 * SEG) dcap (SS + O4 + 8) (SS + O3 + 8) (SS + O2 + 8) (DST + dcap - 7) w64 k4 k2
          (SS + O2 + p2) (DST + SEG) (DST + 2 * SEG) k1 (DST + dcap) (DT + 4) j0).
  Notation SPLX v24 v32 v40 v48 v64 v72 v80 v88 v112 j0 :=
    (SPLB desc (DST + 3 * SEG) v24 v32 v40 v48 (DST + dcap - 7) v64 v72 v80 v88
          (DST + SEG) (DST + 2 * SEG) v112 (DST + dcap) (DT + 4) j0).
  Notation BDS c b p O jp := (BD4 c b (SS + O + p) (SS + O) jp).

  (* [comment removed for export] *)
  Notation ARGS l := (l ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 DST dcap SS DT mtl tl lo src cbs L1 L2 L3 L4 SEG)
    (only parsing).
  Notation Y1HEAD' Q0 := (ARGS Y1HEAD Q0).
  Notation Y1R2' Q0 := (ARGS Y1R2 Q0).
  Notation Y1REL' Q0 := (ARGS Y1REL Q0).
  Notation Y1EXIT' := (ARGS Y1EXIT).
  Notation YB4 l := (l ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 DST dcap SS DT mtl tl lo src cells cbs
                       TOK ECB LCB MTL TLM D0 DP DC DL S0 SL NSM BYS DT0 CBL DJ1 DJ3 LOS SP16 SP47 DT4 L1 L2 L3 L4 SEG HL HQ HQ2)
    (only parsing).
  Notation Y1C2' Q0 := (ARGS Y1C2 Q0).
  Notation Y1C3' Q0 := (ARGS Y1C3 Q0).
  Notation Y1C4' Q0 := (ARGS Y1C4 Q0).
  Notation Y1C9' Q0 := (ARGS Y1C9 Q0).

  Lemma y4s1_rel : forall Q0, Y1HEAD' Q0 -> Y1EXIT' -> Y1REL' Q0.
  Proof using All.
    intros Q0 HD EX.
    assert (C3 : Y1C3' Q0) by exact (YB4 y4s1s_c3 Q0 (YB4 y4s1_c4 Q0 HD EX) (YB4 y4s1_c9 Q0 HD EX)).
    assert (C2 : Y1C2' Q0) by exact (YB4 y4s1_r2 Q0 C3).
    exact (YB4 y4s1_r1 Q0 (YB4 y4s1_r1b Q0 C2 C3) C2 C3).
  Qed.

  (* [comment removed for export] *)
  Lemma y4s1_step : forall Q0, Y1EXIT' -> Y1HEAD' (Q0 + 4) -> Y1HEAD' Q0.
  Proof using All.
    intros Q0 EX HD. refine (YB4 y4s1_r12 Q0 (YB4 y4s1_r34 (Q0 + 2) _)).
    replace (Q0 + 2 + 2) with (Q0 + 4) by lia. exact (y4s1_rel (Q0 + 4) HD EX).
  Qed.

  Lemma y4s1_all : Y1EXIT' -> forall (k : nat) Q0, dcap - Q0 <= 4 * Z.of_nat k -> Y1HEAD' Q0.
  Proof using All.
    intros EX k. induction k as [|k IH]; intros Q0 HK.
    - unfold Y1HEAD. intros until xt5. intros GQ _ _ Q48. exfalso. lia.
    - apply (y4s1_step Q0 EX). apply IH. lia.
  Qed.

  (* [comment removed for export] *)
  Lemma y4s1_loop : Y1EXIT' ->
